<?php

namespace App\Http\Controllers\Webhooks;

use App\Http\Controllers\Controller;
use App\Jobs\RecordChannelMessageJob;
use App\Models\ChannelConnection;
use App\Support\Business\BusinessSettings;
use Illuminate\Http\Request;

/**
 * Meta webhook (WhatsApp Cloud API and Instagram Messaging) for ONE workspace's own connection (MASTER-ONLY, Business Suite Prompt 16).
 *
 * Each workspace brings its own Meta app, so every connection has its own callback URL, its own verify token (generated by us, pasted into the Meta dashboard)
 * and its own app secret. That keeps Naara's platform WhatsApp webhook (WhatsAppWebhookController, with its STOP handling for Naara's own users) completely
 * untouched, and means a customer of a workspace is never treated as a customer of Naara.
 *
 *   GET  : the verification handshake, answered only when the verify token matches THIS connection's.
 *   POST : X-Hub-Signature-256 over the RAW body with THIS connection's app secret, compared with hash_equals() before the payload is read; fails closed.
 */
class WorkspaceMetaWebhookController extends Controller
{
    public function __invoke(Request $request, int $connection)
    {
        $conn = ChannelConnection::query()->whereIn('channel', [ChannelConnection::WHATSAPP, ChannelConnection::INSTAGRAM])->find($connection);
        abort_unless($conn !== null, 404);

        if ($request->isMethod('get')) {
            $token = (string) $conn->webhook_secret;

            return $token !== '' && hash_equals($token, (string) $request->query('hub_verify_token', ''))
                ? response((string) $request->query('hub_challenge', ''), 200)
                : response('Forbidden', 403);
        }

        $secret = (string) $conn->secret('app_secret');
        abort_if($secret === '', 401);
        abort_unless(hash_equals('sha256='.hash_hmac('sha256', $request->getContent(), $secret), (string) $request->header('X-Hub-Signature-256', '')), 401);

        if (! $conn->isActive() || ! BusinessSettings::module('inbox')) {
            return response()->json(['ok' => true]);   // acknowledged so Meta does not retry, nothing is filed
        }

        foreach ((array) $request->input('entry', []) as $entry) {
            $conn->channel === ChannelConnection::WHATSAPP ? $this->whatsapp($conn, (array) $entry) : $this->instagram($conn, (array) $entry);
        }

        return response()->json(['ok' => true]);
    }

    private function whatsapp(ChannelConnection $conn, array $entry): void
    {
        foreach ((array) ($entry['changes'] ?? []) as $change) {
            $value = (array) ($change['value'] ?? []);
            // Only messages sent to THIS connection's number (one app can serve several numbers).
            if ((string) ($value['metadata']['phone_number_id'] ?? '') !== $conn->external_id) {
                continue;
            }
            foreach ((array) ($value['messages'] ?? []) as $m) {
                $from = preg_replace('/\D+/', '', (string) ($m['from'] ?? ''));
                $id = (string) ($m['id'] ?? '');
                $type = (string) ($m['type'] ?? 'text');
                // Text is filed as written; anything else is filed as a plain marker so the team knows something arrived.
                $body = $type === 'text' ? (string) ($m['text']['body'] ?? '') : '['.$type.' received]';
                if ($from !== '' && $id !== '' && trim($body) !== '') {
                    RecordChannelMessageJob::dispatch($conn->id, $from, $body, $id, isset($m['timestamp']) ? (int) $m['timestamp'] : null);
                }
            }
        }
    }

    private function instagram(ChannelConnection $conn, array $entry): void
    {
        foreach ((array) ($entry['messaging'] ?? []) as $event) {
            $m = (array) ($event['message'] ?? []);
            $sender = (string) ($event['sender']['id'] ?? '');
            $mid = (string) ($m['mid'] ?? '');
            // Echoes of our own replies, other accounts' events and empty messages are ignored.
            if (! empty($m['is_echo']) || ($m['text'] ?? '') === '' || (string) ($event['recipient']['id'] ?? '') !== $conn->external_id || $sender === '' || $mid === '') {
                continue;
            }
            RecordChannelMessageJob::dispatch($conn->id, $sender, (string) $m['text'], $mid, isset($event['timestamp']) ? (int) floor(((int) $event['timestamp']) / 1000) : null);
        }
    }
}
